    public static SVGPath createIcon(String pathData, double size, Paint fill) {
        SVGPath path = new SVGPath();
        path.setContent(pathData);
        path.setFill(fill);
        path.setScaleX(size / 24.0);
        path.setScaleY(size / 24.0);
        return path;
    }
